//! Everything the webview can reach: commands, events and their error type,
//! exported as typed TypeScript bindings (tauri-specta).
//!
//! To add a command: write it in `commands/` with `#[tauri::command]` and
//! `#[specta::specta]`, register it in [`builder`], then run
//! `cargo test -p calcine` to regenerate `src/lib/bindings.ts`.

pub mod commands;
pub mod error;
pub mod events;

use specta_typescript::Typescript;
use tauri::Wry;
use tauri_specta::{Builder, collect_commands, collect_events};

/// Generated file consumed by the frontend. CI fails if it is out of date.
const BINDINGS_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../src/lib/bindings.ts");

/// Every command and event exposed to the frontend.
pub fn builder() -> Builder<Wry> {
    Builder::<Wry>::new()
        .commands(collect_commands![
            commands::app::app_info,
            commands::app::set_language,
            commands::app::open_url,
            commands::app::save_markdown,
            commands::app::autostart_enabled,
            commands::app::set_autostart,
            commands::updates::check_app_update,
            commands::updates::install_app_update,
            commands::models::list_models,
            commands::models::remove_models,
            commands::models::clean_models,
            commands::models::set_model_type,
            commands::models::parse_model_reference,
            commands::models::pull_model,
            commands::models::import_model,
            commands::models::pick_import_source,
            commands::models::open_models_folder,
            commands::models::aihub_catalog,
            commands::models::search_models,
            commands::models::model_details,
            commands::runtime::runtime_info,
            commands::runtime::chipset,
            commands::runtime::set_chipset,
            commands::runtime::list_chipsets,
            commands::runtime::hardware_info,
            commands::runtime::hardware_usage,
            commands::runtime::check_runtime_update,
            commands::runtime::install_runtime,
            commands::runtime::cached_runtimes,
            commands::jobs::list_jobs,
            commands::jobs::cancel_job,
            commands::jobs::dismiss_job,
            commands::server::gateway_status,
            commands::server::gateway_connection,
            commands::server::start_server,
            commands::server::stop_server,
            commands::server::server_logs,
            commands::server::server_options,
            commands::server::set_server_options,
            commands::server::set_require_api_key,
            commands::server::gateway_settings,
            commands::server::set_gateway_port,
            commands::server::set_allowed_origins,
            commands::server::list_requests,
            commands::server::list_api_keys,
            commands::server::create_api_key,
            commands::server::revoke_api_key,
        ])
        .events(collect_events![
            events::JobUpdated,
            events::GatewayUpdated,
            events::RequestLogged
        ])
        // Byte sizes and timestamps are u64 but always far below 2^53.
        .dangerously_cast_bigints_to_number()
}

pub fn export(builder: &Builder<Wry>) -> Result<(), specta_typescript::Error> {
    builder.export(
        Typescript::default().header(
            "// Generated by tauri-specta from src-tauri. Do not edit.\n\
             // Regenerate with `cargo test -p calcine` or by running the app in debug.",
        ),
        BINDINGS_PATH,
    )
}
